"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import {
  type Candle,
  DAY_MS,
  type MarketRange,
  MORPH_SAMPLES,
  RollingNumber,
  RangeSelector,
  DATE_FULL,
  DATE_SHORT,
  formatAxisPrice,
  formatMoney,
  formatSignedPct,
  monotonePath,
  mulberry32,
  niceTicks,
  resample,
  round2,
  useTween,
  useTweenNumber,
} from "@/components/moneytrees/charts/chart-engine";

const NO_TICKS: Candle[] = [];

export const PAD = { top: 12, right: 60, bottom: 22, left: 12 };
const VOLUME_SHARE = 0.2;
const VOLUME_GAP = 12;

const UP = "var(--spectrum-chart-up)";
const DOWN = "var(--spectrum-chart-down)";
const SURFACE = "var(--spectrum-chart-surface)";
const RISE = "spectrum-mc-rise 420ms cubic-bezier(0.22, 1, 0.36, 1)";
const DRAW = "spectrum-mc-draw 900ms cubic-bezier(0.22, 1, 0.36, 1) both";
const FADE = "spectrum-mc-fade 620ms ease-out both";

export type Variant = "candles" | "area";

export interface ChartLayout {
  w: number;
  h: number;
  plotX0: number;
  plotX1: number;
  plotW: number;
  innerBottom: number;
  volH: number;
  priceY0: number;
  priceY1: number;
  volY0: number;
  volY1: number;
  priceH: number;
  step: number;
  bodyW: number;
}

type PriceY = (v: number) => number;
type IndexX = (i: number) => number;

function colorOf(isUp: boolean) {
  return isUp ? UP : DOWN;
}

function isUpCandle(candle: Candle) {
  return candle.close >= candle.open;
}

function clamp(value: number, lo: number, hi: number) {
  return Math.max(lo, Math.min(hi, value));
}

function riseStyle(reduce: boolean, delay: number): React.CSSProperties {
  return {
    transition: reduce ? undefined : "opacity 160ms ease-out",
    transformBox: "fill-box",
    transformOrigin: "bottom center",
    animation: reduce ? undefined : `${RISE} ${delay}ms both`,
  };
}

function fadeStyle(reduce: boolean): React.CSSProperties | undefined {
  return reduce ? undefined : { animation: FADE };
}

function drawStyle(reduce: boolean): React.CSSProperties | undefined {
  return reduce ? undefined : { strokeDasharray: 1, animation: DRAW };
}

function staggerFor(n: number, i: number) {
  return n <= 1 ? 0 : (i / (n - 1)) * 340;
}

export function initialRangeLabel(ranges: MarketRange[], defaultRange: string) {
  return ranges.find((r) => r.label === defaultRange)?.label ?? ranges[ranges.length - 1]!.label;
}

export function layoutFor(
  width: number,
  height: number,
  showVolume: boolean,
  n: number,
): ChartLayout {
  const w = Math.max(width, 260);
  const plotX0 = PAD.left;
  const plotX1 = w - PAD.right;
  const plotW = Math.max(1, plotX1 - plotX0);
  const innerTop = PAD.top;
  const innerBottom = height - PAD.bottom;
  const volH = showVolume ? Math.round((innerBottom - innerTop) * VOLUME_SHARE) : 0;
  const priceY0 = innerTop;
  const priceY1 = innerBottom - (showVolume ? volH + VOLUME_GAP : 0);
  const step = plotW / Math.max(n, 1);
  return {
    w,
    h: height,
    plotX0,
    plotX1,
    plotW,
    innerBottom,
    volH,
    priceY0,
    priceY1,
    volY0: innerBottom - volH,
    volY1: innerBottom,
    priceH: Math.max(1, priceY1 - priceY0),
    step,
    bodyW: Math.max(1, Math.min(step * 0.68, 18)),
  };
}

function rawDomainOf(view: Candle[], variant: Variant): readonly [number, number] {
  if (!view.length) return [0, 1];
  let lo = Infinity;
  let hi = -Infinity;
  for (const c of view) {
    const low = variant === "area" ? c.close : c.low;
    const high = variant === "area" ? c.close : c.high;
    if (low < lo) lo = low;
    if (high > hi) hi = high;
  }
  const pad = (hi - lo) * 0.12 || Math.abs(hi) * 0.02 || 1;
  return [lo - pad, hi + pad];
}

function timeTickIndices(n: number, plotW: number, plotX0: number): number[] {
  if (!n) return [];
  const want = Math.max(2, Math.min(6, Math.floor(plotW / 96)));
  const gap = Math.max(1, Math.floor((n - 1) / (want - 1 || 1)));
  const out: number[] = [];
  for (let i = 0; i < n; i += gap) out.push(i);
  const minGap = 62;
  const xOf = (i: number) => plotX0 + (plotW / Math.max(n, 1)) * (i + 0.5);
  if (out[out.length - 1] !== n - 1) {
    while (out.length && xOf(n - 1) - xOf(out[out.length - 1]!) < minGap) out.pop();
    out.push(n - 1);
  }
  return out;
}

function nextTick(rand: () => number, last: Candle): Candle {
  const shock = (rand() - 0.48) * 0.018;
  const close = round2(Math.max(0.01, last.close * (1 + shock)));
  return {
    t: last.t + DAY_MS,
    open: last.close,
    high: round2(Math.max(last.close, close) * (1 + rand() * 0.006)),
    low: round2(Math.min(last.close, close) * (1 - rand() * 0.006)),
    close,
    volume: Math.round((0.6 + rand()) * 1_000_000),
  };
}

export function useLiveTicks(live: boolean, data: Candle[]) {
  const [tickState, setTicks] = React.useState<Candle[]>([]);
  const ticks = live ? tickState : NO_TICKS;
  const [flash, setFlash] = React.useState<"up" | "down" | null>(null);

  React.useEffect(() => {
    if (!live) return;
    const rand = mulberry32(0x5eed);
    let last = data[data.length - 1]!;
    const id = window.setInterval(() => {
      const next = nextTick(rand, last);
      last = next;
      setFlash(next.close >= next.open ? "up" : "down");
      setTicks((prev) => [...prev, next].slice(-120));
    }, 1600);
    return () => window.clearInterval(id);
  }, [live, data]);

  React.useEffect(() => {
    if (!flash) return;
    const id = window.setTimeout(() => setFlash(null), 620);
    return () => window.clearTimeout(id);
  }, [flash, ticks.length]);

  return { ticks, flash };
}

export function useRangeView(
  data: Candle[],
  ticks: Candle[],
  ranges: MarketRange[],
  rangeLabel: string,
) {
  const series = React.useMemo(() => (ticks.length ? [...data, ...ticks] : data), [data, ticks]);
  const range = ranges.find((r) => r.label === rangeLabel) ?? ranges[ranges.length - 1]!;
  return React.useMemo(() => {
    const bars = range.bars;
    if (bars == null || bars >= series.length) return series;
    return series.slice(series.length - bars);
  }, [series, range.bars]);
}

export function usePriceScale(
  view: Candle[],
  variant: Variant,
  reduce: boolean,
  { priceY1, priceH }: ChartLayout,
) {
  const rawDomain = React.useMemo(() => rawDomainOf(view, variant), [view, variant]);
  const [domLo = 0, domHi = 0] = useTween([rawDomain[0], rawDomain[1]], {
    duration: 560,
    enabled: !reduce,
  });

  const priceY = React.useCallback<PriceY>(
    (v) => {
      const span = domHi - domLo || 1;
      return priceY1 - ((v - domLo) / span) * priceH;
    },
    [domHi, domLo, priceY1, priceH],
  );

  const priceAt = React.useCallback(
    (y: number) => domLo + ((priceY1 - y) / priceH) * (domHi - domLo),
    [domLo, domHi, priceY1, priceH],
  );

  const priceTicks = React.useMemo(() => niceTicks(domLo, domHi, 5), [domLo, domHi]);

  return { priceY, priceAt, priceTicks };
}

const KEY_STEP: Record<string, number> = { ArrowLeft: -1, ArrowRight: 1, Escape: 0 };

export function useHover(
  n: number,
  { w, h, plotX0, step, priceY0, priceY1 }: ChartLayout,
  svgRef: React.RefObject<SVGSVGElement | null>,
) {
  const [hoverIndex, setHoverIndex] = React.useState<number | null>(null);
  const [hoverY, setHoverY] = React.useState<number | null>(null);

  const pointerToIndex = React.useCallback(
    (clientX: number, clientY: number) => {
      const svg = svgRef.current;
      if (!svg) return;
      const box = svg.getBoundingClientRect();
      const x = ((clientX - box.left) / box.width) * w;
      const y = ((clientY - box.top) / box.height) * h;
      const i = Math.floor((x - plotX0) / step);
      setHoverIndex(clamp(i, 0, n - 1));
      setHoverY(clamp(y, priceY0, priceY1));
    },
    [svgRef, w, h, plotX0, step, n, priceY0, priceY1],
  );

  const clearHover = React.useCallback(() => {
    setHoverIndex(null);
    setHoverY(null);
  }, []);

  const onKeyDown = React.useCallback(
    (event: React.KeyboardEvent) => {
      const dir = KEY_STEP[event.key];
      if (dir === undefined) return;
      event.preventDefault();
      if (dir === 0) return clearHover();
      setHoverIndex((current) => clamp((current ?? n - 1) + dir, 0, n - 1));
      setHoverY(null);
    },
    [n, clearHover],
  );

  return { hoverIndex, hoverY, pointerToIndex, clearHover, onKeyDown };
}

export interface PriceSummary {
  last: Candle | undefined;
  active: Candle | null | undefined;
  shown: Candle | null | undefined;
  baseline: number;
  delta: number;
  dirColor: string;
  lastColor: string;
}

function summarize(view: Candle[], hoverIndex: number | null): PriceSummary {
  const first = view[0];
  const last = view[view.length - 1];
  const active = hoverIndex != null ? view[hoverIndex] : null;
  const shown = active ?? last;
  const baseline = first?.close ?? 0;
  const delta = baseline ? (((shown?.close ?? 0) - baseline) / baseline) * 100 : 0;
  const lastUp = last ? isUpCandle(last) : true;
  return {
    last,
    active,
    shown,
    baseline,
    delta,
    dirColor: colorOf(delta >= 0),
    lastColor: colorOf(lastUp),
  };
}

export function usePriceSummary(view: Candle[], hoverIndex: number | null, reduce: boolean) {
  const summary = summarize(view, hoverIndex);
  const displayPrice = useTweenNumber(summary.shown?.close ?? 0, {
    duration: 260,
    enabled: !reduce && hoverIndex == null,
  });
  return { ...summary, displayPrice };
}

export function useAreaGeometry(
  view: Candle[],
  variant: Variant,
  reduce: boolean,
  { plotX0, plotX1, plotW }: ChartLayout,
  priceY: PriceY,
  baseline: number,
) {
  const closes = React.useMemo(() => view.map((c) => c.close), [view]);
  const morphed = useTween(
    React.useMemo(() => resample(closes), [closes]),
    { duration: 560, enabled: !reduce && variant === "area" },
  );

  const areaPoints = React.useMemo(() => {
    const values = morphed.length === MORPH_SAMPLES ? morphed : resample(closes);
    return values.map((v, i) => ({
      x: plotX0 + (i / (values.length - 1 || 1)) * plotW,
      y: priceY(v),
    }));
  }, [morphed, closes, plotX0, plotW, priceY]);

  const linePath = React.useMemo(
    () => (variant === "area" ? monotonePath(areaPoints) : ""),
    [variant, areaPoints],
  );
  const baselineY = priceY(baseline);

  const areaPath = React.useMemo(() => {
    if (variant !== "area" || !linePath) return "";
    return `${linePath}L${plotX1},${baselineY}L${plotX0},${baselineY}Z`;
  }, [variant, linePath, plotX0, plotX1, baselineY]);

  return { linePath, areaPath, baselineY };
}

export function useTimeTicks(n: number, { plotW, plotX0 }: ChartLayout) {
  return React.useMemo(() => timeTickIndices(n, plotW, plotX0), [n, plotW, plotX0]);
}

export function useMaxVolume(view: Candle[]) {
  return React.useMemo(() => view.reduce((max, c) => Math.max(max, c.volume), 1), [view]);
}

function LivePill({ reduce }: { reduce: boolean }) {
  return (
    <span className="inline-flex items-center gap-1 rounded-full bg-[var(--glass-tint-card)] px-1.5 py-0.5 font-mono text-[9px] uppercase tracking-widest text-muted-foreground">
      <span
        className="size-1.5 rounded-full"
        style={{
          background: UP,
          animation: reduce ? undefined : "spectrum-mc-fade 1.1s ease-in-out infinite alternate",
        }}
      />
      Live
    </span>
  );
}

function HoverReadout({
  active,
  dirColor,
  compactPrice,
}: {
  active: Candle;
  dirColor: string;
  compactPrice: boolean;
}) {
  return (
    <>
      <span className="text-muted-foreground/70">{DATE_FULL.format(active.t)}</span>
      {(["open", "high", "low", "close"] as const).map((key) => (
        <span key={key} className="text-muted-foreground">
          {key[0]!.toUpperCase()}{" "}
          <span
            className="text-foreground"
            style={{ color: key === "close" ? dirColor : undefined }}
          >
            {formatMoney(active[key], compactPrice)}
          </span>
        </span>
      ))}
      <span className="text-muted-foreground">
        V{" "}
        <span className="text-foreground">{formatMoney(active.volume, true).replace("$", "")}</span>
      </span>
    </>
  );
}

export interface MarketChartHeaderProps {
  symbol: string;
  name: string;
  live: boolean;
  reduce: boolean;
  compactPrice: boolean;
  price: number;
  delta: number;
  dirColor: string;
  flash: "up" | "down" | null;
  active: Candle | null | undefined;
  showRangeSelector: boolean;
  ranges: MarketRange[];
  rangeLabel: string;
  onRangeChange: (label: string) => void;
}

export function MarketChartHeader({
  symbol,
  name,
  live,
  reduce,
  compactPrice,
  price,
  delta,
  dirColor,
  flash,
  active,
  showRangeSelector,
  ranges,
  rangeLabel,
  onRangeChange,
}: MarketChartHeaderProps) {
  return (
    <div className="mb-3 flex flex-wrap items-start justify-between gap-x-4 gap-y-3">
      <div className="min-w-0">
        <div className="flex items-baseline gap-2">
          <span className="font-mono text-[12px] font-medium tracking-wide text-foreground">
            {symbol}
          </span>
          <span className="truncate text-[12px] text-muted-foreground">{name}</span>
          {live ? <LivePill reduce={reduce} /> : null}
        </div>

        <div className="mt-1 flex items-end gap-2.5">
          <RollingNumber
            value={price}
            format={(v) => formatMoney(v, compactPrice)}
            animate={!reduce}
            className={cn(
              "font-mono text-[26px] font-medium text-foreground transition-colors duration-300 ",
            )}
          />
          <span
            className="mb-1 rounded-md px-1.5 py-0.5 font-mono text-[12px] tabular-nums transition-colors duration-300"
            style={{
              color: dirColor,
              background: flash
                ? `color-mix(in srgb, ${dirColor} 16%, transparent)`
                : "transparent",
            }}
          >
            {formatSignedPct(delta)}
          </span>
        </div>

        <div
          className="mt-1.5 flex h-4 flex-wrap items-center gap-x-3 font-mono text-[10.5px] tabular-nums transition-opacity duration-200"
          style={{ opacity: active ? 1 : 0 }}
          aria-hidden={!active}
        >
          {active ? (
            <HoverReadout active={active} dirColor={dirColor} compactPrice={compactPrice} />
          ) : null}
        </div>
      </div>

      {showRangeSelector ? (
        <RangeSelector
          ranges={ranges}
          value={rangeLabel}
          onChange={onRangeChange}
          reduce={reduce}
        />
      ) : null}
    </div>
  );
}

export function ChartDefs({
  uid,
  baselineY,
  layout: { plotX0, plotW, priceY0, priceY1 },
}: {
  uid: string;
  baselineY: number;
  layout: ChartLayout;
}) {
  return (
    <defs>
      <linearGradient id={`${uid}-up`} x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stopColor={UP} stopOpacity={0.28} />
        <stop offset="100%" stopColor={UP} stopOpacity={0} />
      </linearGradient>
      <linearGradient id={`${uid}-down`} x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stopColor={DOWN} stopOpacity={0} />
        <stop offset="100%" stopColor={DOWN} stopOpacity={0.28} />
      </linearGradient>
      <clipPath id={`${uid}-above`}>
        <rect
          x={plotX0}
          y={priceY0 - 40}
          width={plotW}
          height={Math.max(0, baselineY - priceY0 + 40)}
        />
      </clipPath>
      <clipPath id={`${uid}-below`}>
        <rect
          x={plotX0}
          y={baselineY}
          width={plotW}
          height={Math.max(0, priceY1 - baselineY + 40)}
        />
      </clipPath>
    </defs>
  );
}

interface PriceAxisProps {
  priceTicks: number[];
  priceY: PriceY;
  layout: ChartLayout;
}

export function PriceGrid({
  priceTicks,
  priceY,
  layout: { plotX0, plotX1, priceY0, priceY1 },
}: PriceAxisProps) {
  return (
    <g shapeRendering="crispEdges">
      {priceTicks.map((tick) => {
        const y = priceY(tick);
        if (y < priceY0 - 1 || y > priceY1 + 1) return null;
        return (
          <line
            key={tick}
            x1={plotX0}
            x2={plotX1}
            y1={y}
            y2={y}
            stroke="currentColor"
            strokeOpacity={0.13}
            strokeDasharray="2 4"
          />
        );
      })}
    </g>
  );
}

export function PriceAxis({
  priceTicks,
  priceY,
  layout: { plotX1, priceY0, priceY1 },
  last,
  hoverY,
}: PriceAxisProps & { last: Candle | undefined; hoverY: number | null }) {
  return (
    <g className="font-mono">
      {priceTicks.map((tick) => {
        const y = priceY(tick);
        if (y < priceY0 - 1 || y > priceY1 + 1) return null;
        const collides =
          (last != null && Math.abs(y - priceY(last.close)) < 13) ||
          (hoverY != null && Math.abs(y - hoverY) < 13);
        if (collides) return null;
        return (
          <text
            key={tick}
            x={plotX1 + 8}
            y={y}
            dominantBaseline="middle"
            fontSize={10.5}
            fill="currentColor"
            className="tabular-nums"
          >
            {formatAxisPrice(tick)}
          </text>
        );
      })}
    </g>
  );
}

export function TimeAxis({
  timeTicks,
  view,
  cx,
  layout: { plotX0, plotX1, innerBottom },
}: {
  timeTicks: number[];
  view: Candle[];
  cx: IndexX;
  layout: ChartLayout;
}) {
  return (
    <g className="font-mono">
      {timeTicks.map((i) => {
        const candle = view[i];
        if (!candle) return null;
        const x = clamp(cx(i), plotX0 + 14, plotX1 - 14);
        return (
          <text
            key={i}
            x={x}
            y={innerBottom + 13}
            textAnchor="middle"
            fontSize={10.5}
            fill="currentColor"
            className="tabular-nums"
          >
            {DATE_SHORT.format(candle.t)}
          </text>
        );
      })}
    </g>
  );
}

export function HoverBand({
  index,
  cx,
  layout: { step, priceY0, innerBottom },
}: {
  index: number;
  cx: IndexX;
  layout: ChartLayout;
}) {
  return (
    <rect
      x={cx(index) - step / 2}
      y={priceY0}
      width={step}
      height={innerBottom - priceY0}
      fill="currentColor"
      opacity={0.05}
    />
  );
}

export function AreaSeries({
  uid,
  reduce,
  areaPath,
  linePath,
  baselineY,
  layout: { plotX0, plotX1 },
}: {
  uid: string;
  reduce: boolean;
  areaPath: string;
  linePath: string;
  baselineY: number;
  layout: ChartLayout;
}) {
  return (
    <g>
      <path
        d={areaPath}
        fill={`url(#${uid}-up)`}
        clipPath={`url(#${uid}-above)`}
        style={fadeStyle(reduce)}
      />
      <path
        d={areaPath}
        fill={`url(#${uid}-down)`}
        clipPath={`url(#${uid}-below)`}
        style={fadeStyle(reduce)}
      />
      <line
        x1={plotX0}
        x2={plotX1}
        y1={baselineY}
        y2={baselineY}
        stroke="currentColor"
        strokeOpacity={0.35}
        strokeDasharray="3 3"
      />
      <path
        d={linePath}
        fill="none"
        stroke={UP}
        strokeWidth={2}
        strokeLinecap="round"
        strokeLinejoin="round"
        clipPath={`url(#${uid}-above)`}
        pathLength={1}
        style={drawStyle(reduce)}
      />
      <path
        d={linePath}
        fill="none"
        stroke={DOWN}
        strokeWidth={2}
        strokeLinecap="round"
        strokeLinejoin="round"
        clipPath={`url(#${uid}-below)`}
        pathLength={1}
        style={drawStyle(reduce)}
      />
    </g>
  );
}

interface SeriesProps {
  view: Candle[];
  cx: IndexX;
  priceY: PriceY;
  layout: ChartLayout;
  hoverIndex: number | null;
  reduce: boolean;
}

function Candlestick({
  candle,
  x,
  priceY,
  bodyW,
  dim,
  hollowUp,
  reduce,
  delay,
}: {
  candle: Candle;
  x: number;
  priceY: PriceY;
  bodyW: number;
  dim: boolean;
  hollowUp: boolean;
  reduce: boolean;
  delay: number;
}) {
  const isUp = isUpCandle(candle);
  const color = colorOf(isUp);
  const yOpen = priceY(candle.open);
  const yClose = priceY(candle.close);
  const bodyH = Math.max(1, Math.abs(yClose - yOpen));
  const hollow = hollowUp && isUp && bodyH > 2;
  return (
    <g style={{ opacity: dim ? 0.32 : 1, ...riseStyle(reduce, delay) }}>
      <line
        x1={x}
        x2={x}
        y1={priceY(candle.high)}
        y2={priceY(candle.low)}
        stroke={color}
        strokeWidth={Math.min(1.5, Math.max(1, bodyW * 0.14))}
      />
      <rect
        x={x - bodyW / 2}
        y={Math.min(yOpen, yClose)}
        width={bodyW}
        height={bodyH}
        rx={Math.min(1.5, bodyW * 0.18)}
        fill={hollow ? SURFACE : color}
        stroke={color}
        strokeWidth={hollow ? 1.25 : 0}
      />
    </g>
  );
}

export function CandleSeries({
  view,
  cx,
  priceY,
  layout: { bodyW },
  hoverIndex,
  reduce,
  hollowUp,
}: SeriesProps & { hollowUp: boolean }) {
  const n = view.length;
  return (
    <g>
      {view.map((candle, i) => (
        <Candlestick
          key={candle.t}
          candle={candle}
          x={cx(i)}
          priceY={priceY}
          bodyW={bodyW}
          dim={hoverIndex != null && hoverIndex !== i}
          hollowUp={hollowUp}
          reduce={reduce}
          delay={staggerFor(n, i)}
        />
      ))}
    </g>
  );
}

export function VolumeSeries({
  view,
  cx,
  layout: { plotX0, plotX1, volH, volY0, volY1, bodyW },
  hoverIndex,
  reduce,
  maxVolume,
}: Omit<SeriesProps, "priceY"> & { maxVolume: number }) {
  const n = view.length;
  return (
    <g>
      {view.map((candle, i) => {
        const barH = Math.max(1, (candle.volume / maxVolume) * volH * 0.88);
        const dim = hoverIndex != null && hoverIndex !== i;
        return (
          <rect
            key={candle.t}
            x={cx(i) - bodyW / 2}
            y={volY1 - barH}
            width={bodyW}
            height={barH}
            rx={Math.min(1.5, bodyW * 0.18)}
            fill={colorOf(isUpCandle(candle))}
            opacity={dim ? 0.12 : 0.3}
            style={riseStyle(reduce, staggerFor(n, i))}
          />
        );
      })}
      <line
        x1={plotX0}
        x2={plotX1}
        y1={volY0 - VOLUME_GAP / 2}
        y2={volY0 - VOLUME_GAP / 2}
        stroke="currentColor"
        strokeOpacity={0.1}
        shapeRendering="crispEdges"
      />
    </g>
  );
}

export function LastPriceMarker({
  last,
  lastColor,
  live,
  reduce,
  n,
  cx,
  priceY,
  layout: { plotX0, plotX1 },
}: {
  last: Candle;
  lastColor: string;
  live: boolean;
  reduce: boolean;
  n: number;
  cx: IndexX;
  priceY: PriceY;
  layout: ChartLayout;
}) {
  const y = priceY(last.close);
  return (
    <g>
      <line
        x1={plotX0}
        x2={plotX1}
        y1={y}
        y2={y}
        stroke={lastColor}
        strokeOpacity={0.55}
        strokeWidth={1}
        strokeDasharray="4 4"
      />
      <rect x={plotX1 + 3} y={y - 9} width={PAD.right - 8} height={18} rx={4} fill={lastColor} />
      <text
        x={plotX1 + 3 + (PAD.right - 8) / 2}
        y={y}
        textAnchor="middle"
        dominantBaseline="middle"
        fontSize={10.5}
        fontWeight={600}
        fill={SURFACE}
        className="font-mono tabular-nums"
      >
        {formatAxisPrice(last.close)}
      </text>
      {live && !reduce ? (
        <>
          <circle
            cx={cx(n - 1)}
            cy={y}
            r={4}
            fill={lastColor}
            style={{ animation: "spectrum-mc-ping 1.6s ease-out infinite" }}
          />
          <circle cx={cx(n - 1)} cy={y} r={3} fill={lastColor} />
        </>
      ) : null}
    </g>
  );
}

function HoverPriceTag({
  hoverY,
  priceAt,
  layout: { plotX0, plotX1 },
}: {
  hoverY: number;
  priceAt: (y: number) => number;
  layout: ChartLayout;
}) {
  return (
    <>
      <line
        x1={plotX0}
        x2={plotX1}
        y1={hoverY}
        y2={hoverY}
        stroke="currentColor"
        strokeOpacity={0.45}
        strokeDasharray="3 3"
      />
      <rect
        x={plotX1 + 3}
        y={hoverY - 9}
        width={PAD.right - 8}
        height={18}
        rx={4}
        className="fill-foreground"
      />
      <text
        x={plotX1 + 3 + (PAD.right - 8) / 2}
        y={hoverY}
        textAnchor="middle"
        dominantBaseline="middle"
        fontSize={10.5}
        fontWeight={600}
        className="fill-foreground font-mono tabular-nums"
      >
        {formatAxisPrice(priceAt(hoverY))}
      </text>
    </>
  );
}

export function HoverOverlay({
  index,
  candle,
  hoverY,
  reduce,
  cx,
  priceY,
  priceAt,
  layout,
}: {
  index: number;
  candle: Candle;
  hoverY: number | null;
  reduce: boolean;
  cx: IndexX;
  priceY: PriceY;
  priceAt: (y: number) => number;
  layout: ChartLayout;
}) {
  const { plotX0, plotX1, priceY0, innerBottom } = layout;
  const x = cx(index);
  return (
    <g
      style={{ transition: reduce ? undefined : "transform 110ms cubic-bezier(0.22, 1, 0.36, 1)" }}
    >
      <line
        x1={x}
        x2={x}
        y1={priceY0}
        y2={innerBottom}
        stroke="currentColor"
        strokeOpacity={0.45}
        strokeDasharray="3 3"
      />
      {hoverY != null ? <HoverPriceTag hoverY={hoverY} priceAt={priceAt} layout={layout} /> : null}

      <g transform={`translate(${clamp(x, plotX0 + 28, plotX1 - 28)}, ${innerBottom + 4})`}>
        <rect x={-27} y={0} width={54} height={16} rx={4} className="fill-foreground" />
        <text
          x={0}
          y={8.5}
          textAnchor="middle"
          dominantBaseline="middle"
          fontSize={10}
          fontWeight={600}
          className="fill-foreground font-mono tabular-nums"
        >
          {DATE_SHORT.format(candle.t)}
        </text>
      </g>

      <circle
        cx={x}
        cy={priceY(candle.close)}
        r={4.5}
        fill={SURFACE}
        stroke={colorOf(isUpCandle(candle))}
        strokeWidth={2}
      />
    </g>
  );
}
